create extension if not exists "pgcrypto";

create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text, timezone text not null default 'Africa/Johannesburg', currency text not null default 'ZAR', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.life_areas (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, slug text not null, color text not null, weight numeric not null check (weight >= 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,slug));
create table public.seasons (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, name text not null, theme text not null, statement text, starts_on date not null, ends_on date not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check (ends_on >= starts_on));
create type public.goal_type as enum ('binary','count','numeric','currency','duration','milestone','consistency','qualitative');
create table public.goals (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, season_id uuid not null references public.seasons(id) on delete cascade, area_id uuid not null references public.life_areas(id) on delete cascade, title text not null, objective text, goal_type public.goal_type not null, baseline numeric not null default 0, target numeric, current_value numeric not null default 0, weight numeric not null default 1 check(weight >= 0), deadline date, status text not null default 'active', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.goal_updates (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, goal_id uuid not null references public.goals(id) on delete cascade, value numeric, note text, recorded_at timestamptz not null default now(), created_at timestamptz not null default now());
create table public.goal_evidence (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, goal_id uuid not null references public.goals(id) on delete cascade, kind text not null check(kind in ('url','file','note','measurement')), value text not null, created_at timestamptz not null default now());
create table public.daily_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entry_date date not null, mood smallint check(mood between 1 and 10), energy smallint check(energy between 1 and 10), stress smallint check(stress between 1 and 10), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(user_id,entry_date));
create table public.deep_work_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, area_id uuid not null references public.life_areas(id) on delete cascade, entry_date date not null, minutes integer not null check(minutes > 0), project text, description text, created_at timestamptz not null default now());
create table public.journal_entries (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, entry_type text not null check(entry_type in ('reflection','win','lesson','struggle','idea','prayer','career','business','fitness')), title text, content text not null, entry_date date not null default current_date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.milestones (id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, season_id uuid references public.seasons(id) on delete set null, area_id uuid references public.life_areas(id) on delete set null, title text not null, achieved_at timestamptz, created_at timestamptz not null default now());

alter table public.profiles enable row level security; alter table public.life_areas enable row level security; alter table public.seasons enable row level security; alter table public.goals enable row level security; alter table public.goal_updates enable row level security; alter table public.goal_evidence enable row level security; alter table public.daily_entries enable row level security; alter table public.deep_work_entries enable row level security; alter table public.journal_entries enable row level security; alter table public.milestones enable row level security;
create policy "own data" on public.profiles using (auth.uid()=id) with check(auth.uid()=id);
create policy "own areas" on public.life_areas using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own seasons" on public.seasons using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own goals" on public.goals using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own goal updates" on public.goal_updates using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own evidence" on public.goal_evidence using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own daily entries" on public.daily_entries using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own deep work" on public.deep_work_entries using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own journal entries" on public.journal_entries using (auth.uid()=user_id) with check(auth.uid()=user_id);
create policy "own milestones" on public.milestones using (auth.uid()=user_id) with check(auth.uid()=user_id);
create index goals_user_season_idx on public.goals(user_id,season_id); create index goal_updates_goal_idx on public.goal_updates(goal_id,recorded_at desc); create index deep_work_user_date_idx on public.deep_work_entries(user_id,entry_date desc); create index journal_user_date_idx on public.journal_entries(user_id,entry_date desc);
